# Find all colored pixels (non-zero)
pixels_by_color = {}
for r in range(8):
    for c in range(8):
        val = input_grid[r][c]
        if val != 0:
            if val not in pixels_by_color:
                pixels_by_color[val] = []
            pixels_by_color[val].append((r, c))

print("\nPixels by color:")
for color, positions in sorted(pixels_by_color.items()):
    print(f"Color {color}: {positions}")

# Check for point symmetry (180 degree rotation around center)
# Center is (3.5, 3.5), so (r,c) -> (7-r, 7-c)
print("\nPoint symmetry check (180° rotation around center):")
def point_symmetric(pos):
    r, c = pos
    return (7-r, 7-c)

for color, positions in sorted(pixels_by_color.items()):
    symmetric_pairs = [(pos, point_symmetric(pos)) for pos in positions]
    print(f"Color {color}: positions and their symmetric counterparts:\n{symmetric_pairs}")
    # Check if symmetric counterparts are also this color
    mirror_positions = set()
    for r, c in positions:
        mirror_positions.add((7-r, 7-c))
    match = positions == mirror_positions
    print(f"  Has symmetric pairs of same color: {match}")

    # If mismatch, what's the symmetric pixel's values?
    if not match:
        print(f"  Actual values at symmetric positions:")
        for r, c in mirror_positions:
            print(f"    ({r},{c}): {input_grid[r][c]}")

